message() {
  if awg_message_format=$(awg_installer_format "$1"); then
    shift
    # An empty leading %s also makes formats starting with -- safe in bash.
    printf "%s$awg_message_format" '' "$@"
  else
    # Unknown diagnostics remain literal, including percent signs and backslashes.
    printf '%s' "$1"
  fi
}
